            policy::Reasoning::Off => json!({"chat_template_kwargs":{"enable_thinking":false}}),
            policy::Reasoning::Low => json!({"reasoning_effort":"low"}),
            policy::Reasoning::Deep => json!({"reasoning_effort":"xhigh"}),
