                turn: turn + 1,
                phase: phase.to_owned(),
                reasoning_effort: payload
                    .get("reasoning_effort")
                    .and_then(Value::as_str)
                    .unwrap_or("thinking_off")
                    .to_owned(),
                tool_choice: payload.get("tool_choice").cloned().unwrap_or(Value::Null),
                tools: payload
                    .get("tools")
                    .and_then(Value::as_array)
                    .map(|tools| {
