                            .filter(|task| !task.trim().is_empty())
                            .ok_or_else(|| {
                                "Task Plan batch update requires task".to_owned()
                            })?;
                        match action {
                            "start" => state.plan.start(task)?,
                            "done" | "drop" => {
                                state.plan.finish(task, action == "drop")?
                            }
                            _ => return Err(
                                "Task Plan batch updates must be start, done, or drop"
                                    .into(),
                            ),
                        }
                    }
                }
                _ => {
