        id: String,
        delta: String,
    },
    ToolCall {
        id: String,
        name: String,
    },
    ToolOutputDelta {
        id: String,
        stream: String,
        content: String,
    },
    /// Emitted synchronously after spawn, before any stdout/stderr. It gives
    /// the Electron persistence layer a durable identity for interrupted runs.
    ToolProcessStarted {
        id: String,
        command: String,
        cwd: String,
        pid: u32,
        pgid: u32,
        session_id: u32,
        started_at: u128,
    },
    ToolResult {
        id: String,
